if(!t||!closed(i,['mode','remaining','movementSpent','interactionsUsed'])||(i.mode!=='record'&&i.mode!=='correct'))throw new Error('Input must contain exactly mode, remaining, movementSpent, and interactionsUsed.');var turn;try{turn=JSON.parse(t.components&&t.components[TURN]);}catch(error){throw new Error('Explicit turn state is corrupt.');}if(!closed(turn,['encounter','round','participant','ordinal','status'])||!ref(turn.encounter)||!ref(turn.round)||!ref(turn.participant)||!integer(turn.ordinal,0,99))throw new Error('Explicit turn state is invalid.');var next={turn:{entityId:t.id},remaining:i.remaining,movementSpent:i.movementSpent,interactionsUsed:i.interactionsUsed};if(!valid(next))throw new Error('Turn budget must use bounded counts and exact metre movement entries.');var raw=t.components&&t.components[BUDGET],previous=null;if(raw){try{previous=typeof raw==='string'?JSON.parse(raw):raw;}catch(error){throw new Error('Existing turn budget is corrupt.');}if(!valid(previous))throw new Error('Existing turn budget is invalid.');}if(i.mode==='record'&&raw)throw new Error('Turn budget is already recorded.');if(i.mode==='correct'&&!raw)throw new Error('Turn budget is absent.');return {narration:t.name+' budget is '+(i.mode==='record'?'recorded.':'corrected.'),data:{mode:i.mode,turnId:t.id,previous:previous,budget:next},effects:[{type:i.mode==='record'?'component.add':'component.set',entityId:t.id,definitionId:BUDGET,data:JSON.stringify(next)}],events:[],notifications:[]};
